-- V2 additive branding; retain NULL on immutable pre-V2 revisions.
ALTER TABLE px_self_certificate_revisions ADD COLUMN IF NOT EXISTS branding_manifest JSON;
DO 'BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = ''ck_self_revision_branding'' AND conrelid = ''px_self_certificate_revisions''::regclass) THEN ALTER TABLE px_self_certificate_revisions ADD CONSTRAINT ck_self_revision_branding CHECK (schema_version < 2 OR branding_manifest IS NOT NULL); END IF; END;';
CREATE OR REPLACE FUNCTION guard_self_revision() RETURNS trigger AS 'BEGIN IF to_jsonb(NEW.id) IS DISTINCT FROM to_jsonb(OLD.id) OR to_jsonb(NEW.owner_account_id) IS DISTINCT FROM to_jsonb(OLD.owner_account_id) OR to_jsonb(NEW.background_asset_id) IS DISTINCT FROM to_jsonb(OLD.background_asset_id) OR to_jsonb(NEW.stamp_asset_id) IS DISTINCT FROM to_jsonb(OLD.stamp_asset_id) OR to_jsonb(NEW.config) IS DISTINCT FROM to_jsonb(OLD.config) OR to_jsonb(NEW.font_manifest) IS DISTINCT FROM to_jsonb(OLD.font_manifest) OR to_jsonb(NEW.renderer_version) IS DISTINCT FROM to_jsonb(OLD.renderer_version) OR to_jsonb(NEW.schema_version) IS DISTINCT FROM to_jsonb(OLD.schema_version) OR to_jsonb(NEW.created_at) IS DISTINCT FROM to_jsonb(OLD.created_at) OR to_jsonb(NEW.branding_manifest) IS DISTINCT FROM to_jsonb(OLD.branding_manifest) OR (NEW.origin_model_id IS DISTINCT FROM OLD.origin_model_id AND NEW.origin_model_id IS NOT NULL) THEN RAISE EXCEPTION ''SELF_CERTIFICATE_IMMUTABLE'' USING ERRCODE = ''23514''; END IF; RETURN NEW; END;' LANGUAGE plpgsql;
